<?php
$summary=$summary??[]; $tasks=$tasks??[]; $logs=$logs??[]; $checkin=$checkin??[]; $message=$message??''; $error=$error??''; $siteCfg=(new \App\Models\SettingModel())->getSiteConfig();
$isTaskCenter = (string)($_GET['path'] ?? '') === 'tasks';
$tabRaw = (string)($_GET['tab'] ?? ($isTaskCenter ? 'tasks' : 'overview'));
$tab = in_array($tabRaw, ['overview','tasks','logs'], true) ? $tabRaw : 'overview';
function growth_task_reward_text(array $task): string { return (new \App\Services\TaskService())->rewardText($task); }
function growth_cycle_label(string $cycle): string { return ['once'=>'一次性','daily'=>'每日','weekly'=>'每周','monthly'=>'每月','permanent'=>'长期','limited'=>'限时'][$cycle] ?? $cycle; }
function growth_category_label(string $category): string { return ['newbie'=>'新手任务','daily'=>'每日任务','weekly'=>'每周任务','activity'=>'活动任务','normal'=>'普通任务'][$category] ?? '普通任务'; }
function growth_task_action_url(array $task): string {
    $action = (string)($task['action_key'] ?? $task['action'] ?? '');
    if (str_contains($action, 'thread_publish')) return '/index.php?path=publish';
    if (str_contains($action, 'post_publish')) return '/index.php';
    if (str_contains($action, 'email_verified')) return '/index.php?path=me';
    if (str_contains($action, 'verification')) return '/index.php?path=verification/apply';
    if (str_contains($action, 'oauth_bound')) return '/index.php?path=oauth/bindings';
    if (str_contains($action, 'profile_completed')) return '/index.php?path=me/edit';
    if (str_contains($action, 'follow_user')) return '/index.php';
    if (str_contains($action, 'favorite_thread')) return '/index.php';
    return '/index.php';
}
function growth_action_label(string $action, string $remark = ''): string {
    if ($action === 'task_reward') {
        if (preg_match('/完成任务「([^」]+)」/u', $remark, $m)) return '完成任务：' . $m[1];
        return '完成任务';
    }
    return [
        'login_daily'=>'每日登录', 'thread_publish'=>'发布帖子', 'post_publish'=>'发布回复',
        'thread_liked'=>'帖子被点赞', 'post_liked'=>'回复被点赞', 'email_verified'=>'邮箱验证',
        'verification_approved'=>'认证通过', 'thread_reward_sent'=>'打赏他人', 'thread_reward_received'=>'收到打赏',
        'profile_completed'=>'完善资料', 'follow_user'=>'关注用户', 'favorite_thread'=>'收藏帖子', 'oauth_bound'=>'绑定登录方式',
        'admin_adjust'=>'系统调整'
    ][$action] ?? '经验变动';
}
?>
