gn:center}.checkin-day.is-done{background:rgba(255,255,255,.22)}.checkin-day.is-today{outline:2px solid rgba(255,255,255,.72);outline-offset:2px}.checkin-day b{display:block;font-size:12px}.checkin-icon{width:30px;height:30px;margin:7px auto;border-radius:12px;background:rgba(255,255,255,.92);color:#0f766e;display:grid;place-items:center;font-weight:950}.checkin-day span{display:block;font-size:11px;line-height:1.35;opacity:.92}.checkin-note{margin-top:12px;font-size:12px;line-height:1.6;opacity:.86}.checkin-level-meter{margin-top:16px;border:1px solid rgba(255,255,255,.24);border-radius:18px;background:rgba(15,23,42,.16);padding:14px}.checkin-exp-value{font-size:22px;font-weight:950;letter-spacing:-.03em}.checkin-meter-track{height:18px;border-radius:999px;background:rgba(255,255,255,.88);overflow:hidden;margin:14px 0 13px}.checkin-meter-fill{height:100%;width:var(--p,0%);border-radius:999px;background:linear-gradient(90deg,#bef264,#22c55e)}.checkin-meter-row{display:grid;grid-template-columns:80px minmax(0,1fr) 80px;gap:10px;align-items:center}.checkin-meter-row b{font-size:20px}.checkin-meter-row span{text-align:center;font-size:16px;font-weight:800;opacity:.92}.level-line{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.level-num{font-size:28px;font-weight:950;color:var(--text-main,#0f172a)}.muted{color:var(--text-soft,#64748b);font-size:13px;line-height:1.7}.progress-bar{height:10px;border-radius:999px;background:var(--input-bg,#f8fafc);overflow:hidden;margin:12px 0}.progress-fill{height:100%;border-radius:999px;background:var(--primary,#0284c7);width:var(--p,0%)}.next-level-box{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:14px}.next-level-box div{border:1px solid var(--line-soft,#e2e8f0);border-radius:14px;background:var(--input-bg,#f8fafc);padding:10px 12px}.next-level-box span{display:block;color:var(--text-muted,#94a3b8);font-size:12px;font-weight:900}.next-level-box strong{display:block;margin-top:5px;color:var(--text-main,#0f172a);font-size:17px;font-weight:950}.task-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:10px}.task-card{border:1px solid var(--line-soft,#e2e8f0);border-radius:16px;padding:13px;background:var(--input-bg,#f8fafc)}.task-card h3{margin:0 0 6px;font-size:15px;color:var(--text-main,#0f172a)}.task-meta{display:flex;gap:6px;flex-wrap:wrap;margin:9px 0}.pill{display:inline-flex;height:22px;align-items:center;border-radius:999px;padding:0 8px;font-size:11px;font-weight:900;background:#e0f2fe;color:#0284c7}.task-actions{display:flex;gap:8px;align-items:center;margin-top:10px}.task-actions .btn{height:30px!important;padding:0 10px!important;border-radius:999px!important;font-size:12px!important}.task-actions textarea{min-height:70px}.alert{padding:10px 12px;border-radius:14px;margin-bottom:12px;font-size:13px}.alert.ok{background:#dcfce7;color:#15803d}.alert.err{background:#fef2f2;color:#b91c1c}.log-list{display:grid;gap:8px}.log-row{display:grid;grid-template-columns:80px minmax(0,1fr) auto;gap:10px;align-items:center;border-bottom:1px solid var(--line-soft,#e2e8f0);padding:8px 0}.log-row:last-child{border-bottom:0}.exp-pos{color:#16a34a;font-weight:950}.exp-neg{color:#ef4444;font-weight:950}@media(max-width:640px){.next-level-box{grid-template-columns:1fr}.growth-page{padding:14px 12px 104px}.growth-card{border-radius:18px;padding:16px}.growth-head{align-items:flex-start}.log-row{grid-template-columns:60px minmax(0,1fr);}.log-row .time{grid-column:2}.level-num{font-size:24px}.checkin-rewards{grid-template-columns:repeat(4,minmax(0,1fr))}.checkin-top{display:grid}.checkin-btn{width:100%}.checkin-meter-row{grid-template-columns:54px minmax(0,1fr) 54px}.checkin-meter-row b{font-size:16px}.checkin-meter-row span{font-size:13px}}
</style></head><body><?php require dirname(__DIR__) . '/layouts/topbar.php'; ?><main class="growth-page"><div class="growth-shell"><div class="growth-head"><div class="growth-title"><?= $isTaskCenter ? '任务中心' : '成长中心' ?></div><a class="btn btn-light" style="text-decoration:none;" href="/index.php?path=me">返回个人中心</a></div><?php if($message): ?><div class="alert ok"><?= htmlspecialchars($message) ?></div><?php endif; ?><?php if($error): ?><div class="alert err"><?= htmlspecialchars($error) ?></div><?php endif; ?>
<nav class="growth-tabs"><?php if(!$isTaskCenter): ?><a class="growth-tab <?= $tab === 'overview' ? 'active' : '' ?>" href="/index.php?path=growth&tab=overview">成长概览</a><a class="growth-tab <?= $tab === 'logs' ? 'active' : '' ?>" href="/index.php?path=growth&tab=logs">经验记录</a><?php else: ?><a class="growth-tab active" href="/index.php?path=tasks">任务中心 <?= count($tasks) ?></a><?php endif; ?></nav>
<?php if ($tab === 'overview'): ?>
<section class="growth-card checkin-hero">
  <div class="checkin-top"><div><div class="checkin-kicker">CLAY DAILY</div><div class="checkin-title">每日签到</div><div class="checkin-streak">已连续签到 <?= (int)($checkin['streak_days'] ?? 0) ?> 天 · 今日<?= !empty($checkin['today_checked']) ? '已签到' : '待签到' ?></div></div><form method="post" action="/index.php?path=growth/checkin"><?= csrf_field() ?><button class="checkin-btn" type="submit" <?= !empty($checkin['today_checked']) ? 'disabled' : '' ?>><?= !empty($checkin['today_checked']) ? '今日已签到' : '立即签到' ?></button></form></div>
  <div class="checkin-level-meter"><div class="checkin-exp-value">经验值：<?= (int)($summary['total_exp'] ?? 0) ?></div><div class="checkin-meter-track"><div class="checkin-meter-fill" style="--p:<?= min(100, max(0, (int)round((($summary['progress_current']??0)/max(1,($summary['progress_total']??1)))*100))) ?>%"></div></div><div class="checkin-meter-row"><b>Lv.<?= (int)($summary['level']??1) ?></b><span><?php if(!empty($summary['next_level'])): ?>距离下一等级还差 <?= (int)$summary['need_exp'] ?> 经验<?php else: ?>已达最高等级<?php endif; ?></span><b style="text-align:right;"><?php if(!empty($summary['next_level'])): ?>Lv.<?= (int)$summary['next_level'] ?><?php else: ?>MAX<?php endif; ?></b></div></div>
  <div class="checkin-rewards"><?php foreach(($checkin['rewards'] ?? []) as $i=>$r): ?><?php $done=(int)($checkin['streak_days'] ?? 0)>$i; $today=((int)($checkin['week_index'] ?? 0)===$i); ?><div class="checkin-day <?= $done ? 'is-done' : '' ?> <?= $today ? 'is-today' : '' ?>"><b>第 <?= (int)$r['day'] ?> 天</b><div class="checkin-icon"><?= $done ? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" style="width:18px;height:18px;"><path d="M20 6 9 17l-5-5"></path></svg>' : '+' ?></div><span>+<?= (int)$r['exp'] ?> 经验</span><span>+<?= currency_trim_amount((float)$r['coin']) ?> <?= htmlspecialchars(currency_name_by_code((string)($r['currency'] ?? ''))) ?></span></div><?php endforeach; ?></div>
  <div class="checkin-note">连续签到每 7 天一轮；断签后从第 1 天重新开始。签到经验直接计入成长等级。</div>
</section>
<?php elseif ($tab === 'tasks'): ?>
<section class="growth-card"><h2 style="margin:0 0 12px;font-size:18px;">任务中心</h2><div class="task-grid"><?php foreach($tasks as $task): ?><?php $p=$task['user_progress']??[]; $status=(string)($p['status']??'doing'); $progress=(int)($p['progress']??0); $target=max(1,(int)($p['target_count']??$task['target_count']??1)); ?><div class="task-card"><h3><?= htmlspecialchars($task['title']) ?></h3><div class="muted"><?= htmlspecialchars((string)$task['description']) ?></div><div class="task-meta"><span class="pill"><?= htmlspecialchars(growth_category_label((string)($task['category'] ?? 'normal'))) ?></span><span class="pill"><?= htmlspecialchars(growth_cycle_label((string)$task['cycle_type'])) ?></span><span class="pill">进度 <?= min($progress,$target) ?> / <?= $target ?></span><span class="pill"><?= htmlspecialchars(growth_task_reward_text($task)) ?></span></div><?php if($status==='completed'): ?><form class="task-actions" method="post" action="/index.php?path=<?= $isTaskCenter ? 'tasks/claim' : 'growth/claim' ?>"><?= csrf_field() ?><input type="hidden" name="task_id" value="<?= (int)$task['id'] ?>"><button class="btn">领取奖励</button></form><?php elseif($status==='claimed'): ?><div class="muted">已领取</div><?php elseif(!empty($task['manual_review'])): ?><form method="post" action="/index.php?path=<?= $isTaskCenter ? 'tasks/submit' : 'growth/submit' ?>" style="display:grid;gap:8px;margin-top:10px;"><?= csrf_field() ?><input type="hidden" name="task_id" value="<?= (int)$task['id'] ?>"><textarea class="textarea" name="content" placeholder="填写提交说明或链接" required></textarea><button class="btn" type="submit">提交审核</button></form><?php else: ?><div class="task-actions"><a class="btn btn-light" href="<?= htmlspecialchars(growth_task_action_url($task)) ?>" style="text-decoration:none;">去完成</a></div><?php endif; ?></div><?php endforeach; ?><?php if(empty($tasks)): ?><div class="muted">暂无可用任务</div><?php endif; ?></div></section>
<?php else: ?>
<section class="growth-card"><h2 style="margin:0 0 12px;font-size:18px;">经验记录</h2><div class="log-list"><?php foreach($logs as $log): ?><div class="log-row"><div class="<?= (int)$log['exp_change']>=0?'exp-pos':'exp-neg' ?>"><?= (int)$log['exp_change']>=0?'+':'' ?><?= (int)$log['exp_change'] ?></div><div><strong><?= htmlspecialchars(growth_action_label((string)$log['action'], (string)$log['remark'])) ?></strong><div class="muted"><?= htmlspecialchars((string)$log['remark']) ?></div></div><div class="muted time"><?= htmlspecialchars((string)$log['created_at']) ?></div></div><?php endforeach; ?><?php if(empty($logs)): ?><div class="muted">暂无经验记录</div><?php endif; ?></div></section>
<?php endif; ?>
</div></main><?php require dirname(__DIR__, 2) . '/layouts/theme-toggle.php'; ?><?php require dirname(__DIR__) . '/layouts/bottom-nav.php'; ?></body></html>
